9		t.is(slugify('[foo] [bar]'), 'foo-bar');
10		t.is(slugify('Foo ÿ'), 'foo-y');
11		t.is(slugify('FooBar'), 'foo-bar');
12		t.is(slugify('fooBar'), 'foo-bar');
13		t.is(slugify('UNICORNS AND RAINBOWS'), 'unicorns-and-rainbows');
14		t.is(slugify('Foo & Bar'), 'foo-and-bar');
15		t.is(slugify('Foo & Bar'), 'foo-and-bar');
16		t.is(slugify('Hællæ, hva skjera?'), 'haellae-hva-skjera');
17		t.is(slugify('Foo Bar2'), 'foo-bar2');
18		t.is(slugify('I ♥ Dogs'), 'i-love-dogs');
19		t.is(slugify('Déjà Vu!'), 'deja-vu');
20		t.is(slugify('fooBar 123 $#%'), 'foo-bar-123');
21		t.is(slugify('foo🦄'), 'foo-unicorn');
22		t.is(slugify('🦄🦄🦄'), 'unicorn-unicorn-unicorn');
23		t.is(slugify('foo&bar'), 'foo-and-bar');
24		t.is(slugify('foo360BAR'), 'foo360-bar');
25		t.is(slugify('FOO360'), 'foo-360');
26		t.is(slugify('FOOBar'), 'foo-bar');
27	});
28	
29	test('decamelize acronyms', t => {
30		t.is(slugify('APISection'), 'api-section');
31		// The word after the acronym has `s` as its second letter, which used to prevent the split.
32		t.is(slugify('HTMLEscape'), 'html-escape');
33		t.is(slugify('XMLMsgBox'), 'xml-msg-box');
34		// The minimum two-character acronym splits from a following capitalized word.
35		t.is(slugify('IDValue'), 'id-value');
36		// The minimum uppercase run also splits from a numeric suffix.
37		t.is(slugify('ID2'), 'id-2');
38		// Acronyms split correctly when preceded by a lowercase word.
39		t.is(slugify('parseXMLDocument'), 'parse-xml-document');
40		// Multiple acronym-to-word boundaries are handled in the same identifier.
41		t.is(slugify('XMLHttpAPIResponse'), 'xml-http-api-response');
42		// Numeric acronym suffixes compose with a following capitalized word.
43		t.is(slugify('HTML5Parser'), 'html-5-parser');
44	
45		// A plural acronym stays intact.
46		t.is(slugify('APIs'), 'apis');
47		t.is(slugify('Util APIs'), 'util-apis');
48		t.is(slugify('APIsAndMore'), 'apis-and-more');
49		t.is(slugify('APIs2'), 'apis2');
50		// A plural acronym remains intact between camel-cased words.
51		t.is(slugify('getAPIsNow'), 'get-apis-now');
52	});
53	
54	test('possessives and contractions', t => {
55		// Straight apostrophes
56		t.is(slugify('Conway\'s Law'), 'conways-law');
57		t.is(slugify('Conway\'s'), 'conways');
58		t.is(slugify('Don\'t Repeat Yourself'), 'dont-repeat-yourself');
59		t.is(slugify('my parents\' rules'), 'my-parents-rules');
60		t.is(slugify('it-s-hould-not-modify-t-his'), 'it-s-hould-not-modify-t-his');
